// Builds the Graph API payload. Deterministic, no AI involvement.
const j = $json;
let cfg = {}, creative = {};
try { cfg = typeof j.platform_config === 'string' ? JSON.parse(j.platform_config) : (j.platform_config || {}); } catch (e) { cfg = {}; }
try { creative = typeof j.creative === 'string' ? JSON.parse(j.creative) : (j.creative || {}); } catch (e) { creative = {}; }

const pageId = cfg.page_id || $env.META_PAGE_ID;
const caption = [String(creative.caption || '').trim(), String(creative.cta || '').trim(), (creative.hashtags || []).join(' ')]
  .filter(Boolean).join('\n\n');

const errors = [];
if (!pageId) errors.push('missing_page_id');
if (!caption) errors.push('missing_caption');
if (!j.storage_ref) errors.push('missing_image_reference');
if (!/^https?:\/\//i.test(String(j.storage_ref || ''))) errors.push('image_reference_not_public_url');

return {
  json: {
    schedule_id: j.schedule_id,
    asset_id: j.asset_id,
    campaign_id: j.campaign_id,
    client_id: j.client_id,
    platform: 'facebook',
    ready: errors.length === 0,
    prep_errors: errors,
    page_id: pageId,
    api_version: $env.META_API_VERSION || 'v21.0',
    caption,
    image_url: j.storage_ref
  }
};

const prep = $('CODE - Facebook Publish Preparation').first().json;
const r = $input.first().json || {};
const postId = r.post_id || r.id || null;
return [{
  json: {
    ...prep,
    status: postId ? 'published' : 'failed',
    platform_post_id: postId,
    published_at: new Date().toISOString(),
    raw_response: r,
    error_detail: postId ? null : { stage: 'publication', platform: 'facebook', error_code: 'no_post_id_returned', message: 'Graph API returned no post identifier', retry_count: 0, timestamp: new Date().toISOString() }
  }
}];

const prep = $('CODE - Facebook Publish Preparation').first().json;
const e = $input.first().json || {};
const code = e.error?.error?.code || e.error?.code || e.code || 'graph_api_error';
const msg = e.error?.error?.message || e.error?.message || e.message || 'Facebook publication failed';
return [{
  json: {
    ...prep,
    status: 'failed',
    platform_post_id: null,
    published_at: null,
    raw_response: e,
    error_detail: { stage: 'publication', platform: 'facebook', error_code: String(code), message: String(msg), retry_count: 3, timestamp: new Date().toISOString() }
  }
}];
